"use client";

import { useEffect, useMemo, useState } from "react";

const DEFAULT_API = process.env.NEXT_PUBLIC_API_BASE || "http://127.0.0.1:8000";
const LS_KEY = "dynasty_radar_league_players";
const LS_KEY_ID = "dynasty_radar_league_id";

async function postJson(url, payload) {
  const res = await fetch(url, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(payload),
  });
  const text = await res.text();
  let body = null;
  try {
    body = JSON.parse(text);
  } catch {
    body = text;
  }
  if (!res.ok) {
    throw new Error(typeof body === "string" ? body : JSON.stringify(body));
  }
  return body;
}

async function getJson(url) {
  const res = await fetch(url);
  const text = await res.text();
  let body = null;
  try {
    body = JSON.parse(text);
  } catch {
    body = text;
  }
  if (!res.ok) {
    throw new Error(typeof body === "string" ? body : JSON.stringify(body));
  }
  return body;
}

function SortableTable({ title, rows, defaultSortKey, limit = 40 }) {
  const [query, setQuery] = useState("");
  const [sortKey, setSortKey] = useState(defaultSortKey || "");
  const [sortDir, setSortDir] = useState("desc");

  const keys = rows && rows.length > 0 ? Object.keys(rows[0]) : [];

  useEffect(() => {
    if (!sortKey && keys.length > 0) {
      setSortKey(keys[0]);
    }
  }, [keys, sortKey]);

  const filtered = useMemo(() => {
    if (!rows || rows.length === 0) {
      return [];
    }
    if (!query.trim()) {
      return rows;
    }
    const q = query.trim().toLowerCase();
    return rows.filter((row) =>
      Object.values(row).some((v) => String(v ?? "").toLowerCase().includes(q))
    );
  }, [rows, query]);

  const sorted = useMemo(() => {
    const out = [...filtered];
    if (!sortKey) {
      return out;
    }
    out.sort((a, b) => {
      const av = a[sortKey];
      const bv = b[sortKey];
      const an = Number(av);
      const bn = Number(bv);
      const bothNum = Number.isFinite(an) && Number.isFinite(bn);

      let cmp = 0;
      if (bothNum) {
        cmp = an - bn;
      } else {
        cmp = String(av ?? "").localeCompare(String(bv ?? ""));
      }
      return sortDir === "asc" ? cmp : -cmp;
    });
    return out;
  }, [filtered, sortKey, sortDir]);

  if (!rows || rows.length === 0) {
    return (
      <section className="stack panel">
        <h3>{title}</h3>
        <p className="muted">No data yet.</p>
      </section>
    );
  }

  const shown = sorted.slice(0, limit);

  function onHeaderClick(k) {
    if (sortKey === k) {
      setSortDir((d) => (d === "asc" ? "desc" : "asc"));
      return;
    }
    setSortKey(k);
    setSortDir("desc");
  }

  return (
    <section className="stack panel">
      <div className="row between">
        <h3>{title}</h3>
        <input
          className="input"
          style={{ maxWidth: 260 }}
          placeholder="Filter rows..."
          value={query}
          onChange={(e) => setQuery(e.target.value)}
        />
      </div>
      <div style={{ overflowX: "auto" }}>
        <table className="table">
          <thead>
            <tr>
              {keys.map((k) => (
                <th key={k} onClick={() => onHeaderClick(k)} style={{ cursor: "pointer" }}>
                  {k}
                  {sortKey === k ? (sortDir === "asc" ? " ▲" : " ▼") : ""}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {shown.map((r, idx) => (
              <tr key={idx}>
                {keys.map((k) => (
                  <td key={`${idx}-${k}`}>{String(r[k] ?? "")}</td>
                ))}
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      <p className="muted">
        Showing {shown.length} of {sorted.length} rows.
      </p>
    </section>
  );
}

export default function LeagueWorkspace() {
  const [apiBase, setApiBase] = useState(DEFAULT_API);
  const [leagueId, setLeagueId] = useState("");
  const [busy, setBusy] = useState(false);
  const [status, setStatus] = useState("idle");

  const [leaguePlayers, setLeaguePlayers] = useState([]);
  const [valuations, setValuations] = useState([]);
  const [lineup, setLineup] = useState(null);
  const [trade, setTrade] = useState(null);
  const [tradeEval, setTradeEval] = useState(null);
  const [fa, setFa] = useState(null);
  const [market, setMarket] = useState([]);
  const [selectedSend, setSelectedSend] = useState([]);
  const [selectedReceive, setSelectedReceive] = useState([]);

  const [myTeam, setMyTeam] = useState("");
  const [partner, setPartner] = useState("");
  const [superflex, setSuperflex] = useState(true);

  useEffect(() => {
    try {
      const raw = localStorage.getItem(LS_KEY);
      const rawId = localStorage.getItem(LS_KEY_ID);
      if (raw) {
        const parsed = JSON.parse(raw);
        if (Array.isArray(parsed)) {
          setLeaguePlayers(parsed);
        }
      }
      if (rawId) {
        setLeagueId(rawId);
      }
    } catch {
      // ignore malformed local storage
    }
  }, []);

  const teams = useMemo(() => {
    const uniq = new Set();
    for (const p of leaguePlayers) {
      if (p.display_name) {
        uniq.add(p.display_name);
      }
    }
    return [...uniq].sort((a, b) => a.localeCompare(b));
  }, [leaguePlayers]);

  const myTeamRoster = useMemo(
    () => leaguePlayers.filter((p) => p.display_name === myTeam),
    [leaguePlayers, myTeam]
  );

  const myTeamValuations = useMemo(
    () => valuations.filter((p) => p.display_name === myTeam),
    [valuations, myTeam]
  );

  useEffect(() => {
    if (!myTeam && teams.length > 0) {
      setMyTeam(teams[0]);
    }
    if (!partner && teams.length > 1) {
      setPartner(teams[1]);
    }
  }, [teams, myTeam, partner]);

  async function loadLeague() {
    if (!leagueId.trim()) {
      setStatus("Enter a Sleeper league ID first.");
      return;
    }
    setBusy(true);
    setStatus("Loading league...");
    try {
      const out = await postJson(`${apiBase}/v1/league/load`, { league_id: leagueId.trim() });
      const players = out.players || [];
      setLeaguePlayers(players);
      setValuations([]);
      setLineup(null);
      setTrade(null);
      setTradeEval(null);
      setFa(null);
      localStorage.setItem(LS_KEY, JSON.stringify(players));
      localStorage.setItem(LS_KEY_ID, leagueId.trim());
      setStatus(`Loaded ${players.length} player rows across ${new Set(players.map((p) => p.display_name)).size} teams.`);
    } catch (err) {
      setStatus(`Load failed: ${err.message}`);
    } finally {
      setBusy(false);
    }
  }

  async function runValuations() {
    if (leaguePlayers.length === 0) {
      setStatus("Load a league first.");
      return;
    }
    setBusy(true);
    setStatus("Running valuations...");
    try {
      let mkt = market;
      if (mkt.length === 0) {
        const outMkt = await getJson(`${apiBase}/v1/market/default`);
        mkt = outMkt.players || [];
        setMarket(mkt);
      }
      const out = await postJson(`${apiBase}/v1/valuations`, {
        roster: leaguePlayers,
        market: mkt,
        superflex,
        ppr: true,
      });
      setValuations(out.players || []);
      setStatus(`Valuations complete (${out.players?.length || 0} players).`);
    } catch (err) {
      setStatus(`Valuation failed: ${err.message}`);
    } finally {
      setBusy(false);
    }
  }

  async function runLineup() {
    if (!myTeam) {
      setStatus("Select your team first.");
      return;
    }
    if (myTeamRoster.length === 0) {
      setStatus("No roster rows found for selected team.");
      return;
    }

    setBusy(true);
    setStatus(`Running lineup for ${myTeam}...`);
    try {
      const out = await postJson(`${apiBase}/v1/lineup/recommend`, {
        roster: myTeamRoster.map((p) => ({ name: p.name, pos: p.pos, team: p.team })),
        superflex,
      });
      setLineup(out);
      setStatus("Lineup complete.");
    } catch (err) {
      setStatus(`Lineup failed: ${err.message}`);
    } finally {
      setBusy(false);
    }
  }

  async function runTradeTargets() {
    if (!myTeam) {
      setStatus("Select your team first.");
      return;
    }
    if (valuations.length === 0) {
      setStatus("Run valuations first.");
      return;
    }

    setBusy(true);
    setStatus("Running trade analysis...");
    try {
      const out = await postJson(`${apiBase}/v1/trade/targets`, {
        my_team: myTeam,
        partner: partner || null,
        players: valuations.map((v) => ({
          name: v.name,
          pos: v.pos,
          display_name: v.display_name,
          true_value: v.true_value,
          market_value: v.market_value,
          edge: v.edge,
          edge_z_adj: v.edge_z_adj,
          WinNowScore: v.WinNowScore,
        })),
      });
      setTrade(out);
      setTradeEval(null);
      setSelectedSend([]);
      setSelectedReceive([]);
      setStatus("Trade analysis complete.");
    } catch (err) {
      setStatus(`Trade failed: ${err.message}`);
    } finally {
      setBusy(false);
    }
  }

  function togglePick(setter, current, name) {
    if (current.includes(name)) {
      setter(current.filter((n) => n !== name));
      return;
    }
    setter([...current, name]);
  }

  async function evaluateTradePackage() {
    if (!trade) {
      setStatus("Run trade analysis first.");
      return;
    }
    if (!partner) {
      setStatus("Select a trade partner first.");
      return;
    }
    if (selectedSend.length === 0 || selectedReceive.length === 0) {
      setStatus("Select at least one send and one receive player.");
      return;
    }
    setBusy(true);
    setStatus("Evaluating selected trade package...");
    try {
      const out = await postJson(`${apiBase}/v1/trade/evaluate`, {
        my_team: myTeam,
        partner,
        send_names: selectedSend,
        receive_names: selectedReceive,
        players: valuations.map((v) => ({
          name: v.name,
          pos: v.pos,
          display_name: v.display_name,
          true_value: v.true_value,
          market_value: v.market_value,
          edge: v.edge,
          edge_z_adj: v.edge_z_adj,
          WinNowScore: v.WinNowScore,
        })),
      });
      setTradeEval(out);
      setStatus("Trade package evaluated.");
    } catch (err) {
      setStatus(`Trade package failed: ${err.message}`);
    } finally {
      setBusy(false);
    }
  }

  async function runFaUpgrades() {
    if (!myTeam) {
      setStatus("Select your team first.");
      return;
    }
    if (myTeamRoster.length === 0) {
      setStatus("No roster rows found for selected team.");
      return;
    }

    setBusy(true);
    setStatus("Running FA upgrades...");
    try {
      let mkt = market;
      if (mkt.length === 0) {
        const outMkt = await getJson(`${apiBase}/v1/market/default`);
        mkt = outMkt.players || [];
        setMarket(mkt);
      }

      const out = await postJson(`${apiBase}/v1/fa/upgrades`, {
        roster: myTeamRoster.map((p) => ({ name: p.name, pos: p.pos, team: p.team })),
        league_roster: leaguePlayers.map((p) => ({
          name: p.name,
          pos: p.pos,
          display_name: p.display_name,
          team: p.team,
        })),
        dp_market: mkt,
        superflex,
      });
      setFa(out);
      setStatus("FA upgrades complete.");
    } catch (err) {
      setStatus(`FA upgrades failed: ${err.message}`);
    } finally {
      setBusy(false);
    }
  }

  return (
    <main className="shell">
      <h1>League Workspace</h1>
      <p className="muted">Load a Sleeper league, select your team, and run all tools without manual JSON.</p>

      <section className="stack panel">
        <div className="row">
          <label className="label grow">
            API Base URL
            <input className="input" value={apiBase} onChange={(e) => setApiBase(e.target.value)} />
          </label>
          <label className="label grow">
            Sleeper League ID
            <input className="input" value={leagueId} onChange={(e) => setLeagueId(e.target.value)} placeholder="1195252934627844096" />
          </label>
        </div>

        <div className="row">
          <button className="button" disabled={busy} onClick={loadLeague} type="button">Load League</button>
          <button className="button" disabled={busy || leaguePlayers.length === 0} onClick={runValuations} type="button">Valuations</button>
          <button className="button" disabled={busy || myTeamRoster.length === 0} onClick={runLineup} type="button">Lineup</button>
          <button className="button" disabled={busy || valuations.length === 0} onClick={runTradeTargets} type="button">Trade</button>
          <button className="button" disabled={busy || myTeamRoster.length === 0} onClick={runFaUpgrades} type="button">FA Upgrades</button>
        </div>

        <div className="row">
          <label className="label grow">
            My Team
            <select className="input" value={myTeam} onChange={(e) => setMyTeam(e.target.value)}>
              {teams.map((t) => (
                <option key={t} value={t}>{t}</option>
              ))}
            </select>
          </label>
          <label className="label grow">
            Trade Partner
            <select className="input" value={partner} onChange={(e) => setPartner(e.target.value)}>
              <option value="">(none)</option>
              {teams.map((t) => (
                <option key={t} value={t}>{t}</option>
              ))}
            </select>
          </label>
          <label className="label">
            Superflex
            <select className="input" value={String(superflex)} onChange={(e) => setSuperflex(e.target.value === "true")}>
              <option value="true">true</option>
              <option value="false">false</option>
            </select>
          </label>
        </div>

        <pre className="pre">{status}</pre>
      </section>

      <SortableTable title="My Team Roster" rows={myTeamRoster} defaultSortKey="pos" />
      <SortableTable title="League Players" rows={leaguePlayers} defaultSortKey="display_name" />
      <SortableTable title="My Team Valuations" rows={myTeamValuations} defaultSortKey="true_value" />

      {lineup ? (
        <section className="stack">
          <h3>Lineup Result</h3>
          <p><strong>Total Projected:</strong> {lineup.total_projected_points}</p>
          <SortableTable title="Starters" rows={lineup.starters || []} defaultSortKey="proj_week" />
          <SortableTable title="Bench" rows={lineup.bench || []} defaultSortKey="proj_week" />
        </section>
      ) : null}

      {trade ? (
        <section className="stack">
          <h3>Trade Result</h3>
          <p><strong>Needs:</strong> {(trade.needs || []).join(", ") || "none"}</p>
          <p><strong>Surplus:</strong> {(trade.surplus || []).join(", ") || "none"}</p>
          <section className="panel stack">
            <h4>Build Trade Package</h4>
            <div className="row">
              <div className="pick-col">
                <p><strong>You Send ({myTeam})</strong></p>
                {(trade.give_candidates || []).slice(0, 25).map((p) => (
                  <label key={`send-${p.name}`} className="pick-item">
                    <input
                      type="checkbox"
                      checked={selectedSend.includes(p.name)}
                      onChange={() => togglePick(setSelectedSend, selectedSend, p.name)}
                    />
                    <span>{p.name} ({p.pos})</span>
                  </label>
                ))}
              </div>
              <div className="pick-col">
                <p><strong>You Receive ({partner || "Partner"})</strong></p>
                {(trade.receive_candidates || []).slice(0, 25).map((p) => (
                  <label key={`recv-${p.name}`} className="pick-item">
                    <input
                      type="checkbox"
                      checked={selectedReceive.includes(p.name)}
                      onChange={() => togglePick(setSelectedReceive, selectedReceive, p.name)}
                    />
                    <span>{p.name} ({p.pos})</span>
                  </label>
                ))}
              </div>
            </div>
            <div className="row">
              <button className="button" type="button" disabled={busy} onClick={evaluateTradePackage}>
                Evaluate Selected Package
              </button>
            </div>
            {tradeEval ? (
              <div className="panel">
                <p><strong>Market Totals:</strong> send {tradeEval.send_total_market.toFixed(1)} | receive {tradeEval.receive_total_market.toFixed(1)} | diff {tradeEval.market_diff.toFixed(1)}</p>
                <p><strong>True Value Totals:</strong> send {tradeEval.send_total_true_value.toFixed(1)} | receive {tradeEval.receive_total_true_value.toFixed(1)} | diff {tradeEval.true_value_diff.toFixed(1)}</p>
                <p><strong>Fairness Score:</strong> {tradeEval.fairness_score.toFixed(3)} (closer to 1.0 is more balanced)</p>
              </div>
            ) : null}
          </section>
          <SortableTable title="Targets" rows={trade.targets || []} defaultSortKey="edge_z_adj" />
          <SortableTable title="Give Candidates" rows={trade.give_candidates || []} defaultSortKey="true_value" />
          <SortableTable title="Receive Candidates" rows={trade.receive_candidates || []} defaultSortKey="true_value" />
          <SortableTable title="Team Strength" rows={trade.team_strength || []} defaultSortKey="TOTAL" />
        </section>
      ) : null}

      {fa ? (
        <section className="stack">
          <h3>FA Upgrades Result</h3>
          <p><strong>Total Projected:</strong> {fa.total_projected_points}</p>
          <SortableTable title="Upgrades" rows={fa.upgrades || []} defaultSortKey="delta_pts" />
          <SortableTable title="FA Pool" rows={fa.fa_pool || []} defaultSortKey="proj_week" />
        </section>
      ) : null}
    </main>
  );
}
